// ここを変えてみよう:Override.class を Deprecated.class に / 12800 を別の金額に
import java.lang.reflect.Method;

@FunctionalInterface interface Formatter {   // 抽象メソッドは1つだけ
    String format(int yen);
}

class Report {
    @Override
    public String toString() { return "Report"; }

    @Deprecated(since = "2.0", forRemoval = true)
    public String oldTitle() { return "旧タイトル"; }
}

Method ts = Report.class.getMethod("toString");
Method old = Report.class.getMethod("oldTitle");
System.out.println("toString に @Override は?   " + ts.isAnnotationPresent(Override.class));
System.out.println("oldTitle に @Deprecated は? " + old.isAnnotationPresent(Deprecated.class));
Deprecated d = old.getAnnotation(Deprecated.class);
System.out.println("  since=" + d.since() + " forRemoval=" + d.forRemoval());
System.out.println("Formatter に @FunctionalInterface は? "
        + Formatter.class.isAnnotationPresent(FunctionalInterface.class));

Formatter f = yen -> String.format("%,d円", yen);   // 抽象メソッド1つなのでラムダで書ける
System.out.println(f.format(12800));

// @Audited を自作して、リフレクションで読む
// ここを変えてみよう:revoke の category を消す / RUNTIME を SOURCE に変える
import java.lang.annotation.*;
import java.lang.reflect.Method;
import java.util.*;

@Retention(RetentionPolicy.RUNTIME)   // 実行時まで残す
@Target(ElementType.METHOD)           // メソッドにだけ付けられる
@interface Audited {
    String value();                       // 要素(必須)
    String category() default "general";  // 要素(省略したら general)
}

class KeyService {
    @Audited("ISSUE_KEY")
    public String issue(String user) { return "key-for-" + user; }

    @Audited(value = "REVOKE_KEY", category = "security")
    public void revoke(String keyId) { }

    public int count() { return 3; }
}

Method[] methods = KeyService.class.getDeclaredMethods();
Arrays.sort(methods, Comparator.comparing(Method::getName)); // 並び順は保証されないので名前順に
for (Method m : methods) {
    Audited a = m.getAnnotation(Audited.class);   // 付いていなければ null
    if (a == null) {
        System.out.println(m.getName() + " : 目印なし");
    } else {
        System.out.println(m.getName() + " : " + a.value() + " / " + a.category());
    }
}
System.out.println("普通に呼ぶ : " + new KeyService().issue("haru") + "(目印だけでは何も起きない)");

// @Audited が付いたメソッドだけ、前後にログを挟んで呼ぶ(フレームワークの縮小版)
// ここを変えてみよう:hello にも @Audited("HELLO") を付ける
import java.lang.annotation.*;
import java.lang.reflect.Method;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Audited { String value(); }

class KeyService {
    @Audited("ISSUE_KEY")
    public String issue(String user) { return "key-for-" + user; }

    public String hello(String user) { return "hello " + user; }
}

// 「読む側」:目印を見て、付いていれば前後に処理を挟む
Object call(Object target, String name, String arg) throws Exception {
    Method m = target.getClass().getMethod(name, String.class);
    Audited a = m.getAnnotation(Audited.class);
    if (a != null) System.out.println("  [AUDIT start] " + a.value());
    Object result = m.invoke(target, arg);          // 本来のメソッドを呼ぶ
    if (a != null) System.out.println("  [AUDIT end]   " + a.value());
    return result;
}

KeyService service = new KeyService();
System.out.println("issue を呼ぶ");
Object r1 = call(service, "issue", "haru");
System.out.println("  結果: " + r1);
System.out.println("hello を呼ぶ");
Object r2 = call(service, "hello", "haru");
System.out.println("  結果: " + r2);

// フィールドの目印を読んで入力チェック(@NotBlank / @Max の縮小版)
// ここを変えてみよう:age を 38 に / memo にも @NotBlank を付ける
import java.lang.annotation.*;
import java.lang.reflect.Field;
import java.util.*;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface NotBlank {}

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Max { int value(); }

class SignupForm {
    @NotBlank private String name;
    @NotBlank private String email;
    @Max(150) private int age;
    private String memo;                  // 目印なし → チェックしない

    SignupForm(String name, String email, int age, String memo) {
        this.name = name; this.email = email; this.age = age; this.memo = memo;
    }
}

List<String> validate(Object form) throws IllegalAccessException {
    List<String> errors = new ArrayList<>();
    Field[] fields = form.getClass().getDeclaredFields();
    Arrays.sort(fields, Comparator.comparing(Field::getName));
    for (Field f : fields) {
        f.setAccessible(true);            // private フィールドも読めるようにする
        Object v = f.get(form);
        if (f.isAnnotationPresent(NotBlank.class) && (v == null || v.toString().isBlank())) {
            errors.add(f.getName() + " は必須です");
        }
        Max max = f.getAnnotation(Max.class);
        if (max != null && (int) v > max.value()) {
            errors.add(f.getName() + " は " + max.value() + " 以下にしてください");
        }
    }
    return errors;
}

System.out.println(validate(new SignupForm("ハル", "", 200, null)));
System.out.println(validate(new SignupForm("モカ", "moka@example.com", 38, "")));

