@RestController
@RequestMapping("/api/keys")
@RequiredArgsConstructor
public class KeyController {

    private final KeyService keyService;

    @PostMapping
    @Audited("ISSUE_KEY")
    public ResponseEntity<KeyResponse> issue(@Valid @RequestBody IssueKeyRequest req) {
        Key key = keyService.issue(req.userId(), req.keyType());
        return ResponseEntity.status(HttpStatus.CREATED).body(KeyResponse.from(key));
    }

    public record IssueKeyRequest(
            @NotBlank String userId,
            @NotNull KeyType keyType) {}

    public record KeyResponse(
            @JsonProperty("key_id") String keyId,
            @JsonFormat(pattern = "yyyy-MM-dd") LocalDate expiresOn) {
        static KeyResponse from(Key k) { return new KeyResponse(k.getId(), k.getExpiresOn()); }
    }
}
